function renderIcon(icon: any, className: string, style?: CSSProperties) {
  if (!icon) return null;
  // 如果是字符串 emoji，直接渲染文本
  if (typeof icon === 'string' && icon.length <= 4) {
    return <span className={className + " flex items-center justify-center text-base"} style={style}>{icon}</span>;
  }
  // 如果是字符串图标名，从映射表取
  if (typeof icon === 'string') {
    const C = ICON_MAP[icon];
    if (C) return <C className={className} style={style} />;
    return null;
  }
  // 如果是组件，直接渲染
  const C = icon;
  return <C className={className} style={style} />;
}

