import { useMemo, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import {
  Calculator,
  TrendingUp,
  Users,
  DollarSign,
  Package,
  ShoppingCart,
  Zap,
  Target,
  Lightbulb,
  Megaphone,
  Star,
  Warehouse,
  Tag,
} from 'lucide-react';
import type { ThemeConfig } from '@/lib/theme';

interface GoalReverseCardProps {
  theme: ThemeConfig;
}

interface ReverseInputs {
  monthlyTarget: number;   // 月销售目标 $
  avgOrderValue: number;   // 平均客单价 $
  conversionRate: number;  // 目标转化率 %
  adOrderRatio: number;    // 广告订单占比 %
  maxACoS: number;         // 广告ACOS %
  linkDailyOrders: number; // 单链接日均出单
  operatingDays: number;   // 每月可运营天数
  currentDailyOrders: number; // 当前日销（选填，用于算增速）
}

const DEFAULT_INPUTS: ReverseInputs = {
  monthlyTarget: 2000,
  avgOrderValue: 25,
  conversionRate: 8,
  adOrderRatio: 35,
  maxACoS: 30,
  linkDailyOrders: 5,
  operatingDays: 30,
  currentDailyOrders: 0,
};

interface ResultItem {
  icon: typeof Calculator;
  label: string;
  value: string;
  formula: string;
  note?: string;
}

function GoalReverseCard({ theme }: GoalReverseCardProps) {
  const [inputs, setInputs] = useState<ReverseInputs>(DEFAULT_INPUTS);

  const results = useMemo(() => {
    const {
      monthlyTarget, avgOrderValue, conversionRate, adOrderRatio,
      maxACoS, linkDailyOrders, operatingDays, currentDailyOrders,
    } = inputs;

    if (operatingDays <= 0 || avgOrderValue <= 0 || conversionRate <= 0 || linkDailyOrders <= 0) {
      return null;
    }

    const monthlyOrders = monthlyTarget / avgOrderValue;           // 月订单数
    const dailyOrders = monthlyOrders / operatingDays;            // 日均订单
    const dailyVisitors = dailyOrders / (conversionRate / 100);   // 日均访客
    const adDailyOrders = dailyOrders * (adOrderRatio / 100);     // 广告订单/天
    const organicDailyOrders = dailyOrders - adDailyOrders;       // 自然订单/天
    const dailyAdSpend = avgOrderValue * adDailyOrders * (maxACoS / 100); // 日均广告花费
    const linksNeeded = Math.ceil(dailyOrders / linkDailyOrders); // 需要的爆款链接数
    const monthlyStock = Math.ceil(monthlyOrders * 1.2);          // 月备货量（含20%安全库存）
    const peakStockWeeks = Math.ceil(monthlyOrders * 1.5 / 4);    // 旺季备货（4-6周取中值约5周）

    const growthRate = currentDailyOrders > 0
      ? ((dailyOrders - currentDailyOrders) / currentDailyOrders * 100).toFixed(1)
      : null;

    const items: ResultItem[] = [
      {
        icon: ShoppingCart,
        label: '日均需要订单',
        value: `${dailyOrders.toFixed(1)} 单/天`,
        formula: `月目标 $${monthlyTarget.toLocaleString()} ÷ 客单价 $${avgOrderValue} ÷ ${operatingDays}天`,
      },
      {
        icon: Users,
        label: '日均需要访客(流量)',
        value: `${dailyVisitors.toFixed(0)} 人/天`,
        formula: `日均订单 ${dailyOrders.toFixed(1)} ÷ 转化率 ${conversionRate}%`,
      },
      {
        icon: Zap,
        label: '广告订单 / 自然订单',
        value: `${adDailyOrders.toFixed(1)} / ${organicDailyOrders.toFixed(1)} 单/天`,
        formula: `日均订单 × 广告占比 ${adOrderRatio}% / 剩下自然单`,
      },
      {
        icon: DollarSign,
        label: '日均广告花费',
        value: `$${dailyAdSpend.toFixed(2)} /天`,
         formula: `客单价 $${avgOrderValue} × 广告订单 ${adDailyOrders.toFixed(1)} × ACOS ${maxACoS}%`,
        note: `月广告费约 $${(dailyAdSpend * operatingDays).toFixed(0)}`,
      },
      {
        icon: TrendingUp,
        label: '需要的爆款链接数',
        value: `${linksNeeded} 条`,
        formula: `日均订单 ${dailyOrders.toFixed(1)} ÷ 单链接日销 ${linkDailyOrders}单（向上取整）`,
        note: '建议留 1-2 条备用链接，防止断货被超',
      },
      {
        icon: Package,
        label: '所需月均备货量',
        value: `${monthlyStock.toLocaleString()} 件/月`,
        formula: `月订单 ${monthlyOrders.toFixed(0)} × 1.2（含20%安全库存）`,
        note: `旺季建议备 ${peakStockWeeks}-${peakStockWeeks + 1}周的货，约 ${Math.ceil(monthlyOrders * 1.5).toLocaleString()} 件`,
      },
    ];

    // 动态建议
    const suggestions = {
      traffic: (() => {
        const v = dailyVisitors;
        if (v < 50) return { level: '起步期', tips: ['主图+标题先优化到点击率1%以上', '开自动广告跑词，每天预算$10-20', '找5-10个同类竞品埋关键词到Search Terms'] };
        if (v < 200) return { level: '成长期', tips: ['自动广告跑出的好词转手动精准', '上站外deal/测评补一波单量和评价', '做视频广告和品牌推广，扩大曝光'] };
        if (v < 500) return { level: '成熟期', tips: ['关键词全覆盖，广告从精准走向广泛', '做品牌旗舰店+Posts+直播引流', '开发站外私域/邮件营销复购'] };
        return { level: '大卖期', tips: ['多链接矩阵+多店铺布局', '拓展平台（TikTok Shop/独立站）', '品牌化+差异化+护城河建设'] };
      })(),
       conversion: (() => {
         const cr = conversionRate;
         if (cr < 5) return { level: '偏低·需警示', levelColor: 'destructive', tips: ['主图第一张一定要有差异化卖点', '价格比竞品低5-10%冲前期转化', '评价少于20个先做vine和早期评论'] };
         if (cr < 8) return { level: '待提升·橙色提醒', levelColor: 'warning', tips: ['优化五点描述和A+页面', '做coupon提升转化', '视频主图能提转化10-30%'] };
         if (cr < 12) return { level: '正常·健康区间', levelColor: 'success', tips: ['测试不同主图CTR，找最优版', '增加QA和review视频', '优化关键词精准度'] };
         return { level: '优秀', levelColor: 'success', tips: ['维持住转化率优势', '扩词放量冲BSR', '把成功经验复制到新品'] };
       })(),
      adRatio: (() => {
        const r = adOrderRatio;
        if (r < 20) return { level: '自然单为主', tip: '广告占比低很好，但要确认自然流量是否健康——BSR排名、关键词自然位是否在首页' };
        if (r < 40) return { level: '健康比例', tip: '广告20-40%是健康区间，自然单占大头说明Listing质量好' };
        if (r < 60) return { level: '广告依赖', tip: '广告占比偏高，要优化自然排名——冲BSR、积累review、做站外引流补自然单' };
        return { level: '广告重度依赖', tip: '危险！广告单占比超60%说明产品几乎没有自然流量，一旦停广告就没单。重点优化SEO和自然排名' };
      })(),
      stock: (() => {
        const links = linksNeeded;
        const monthly = monthlyStock;
        return {
          linksTip: links <= 2 ? '1-2条链接集中精力打爆，不要分散资源' : links <= 4 ? '3-4条链接矩阵，互相配合占坑位' : `${links}条链接布局，建议分梯队：主力款+利润款+引流款`,
          stockTip: `月备货约${monthly.toLocaleString()}件，旺季建议备 ${peakStockWeeks}-${peakStockWeeks + 1}周（约 ${Math.ceil(monthlyOrders * 1.5).toLocaleString()} 件），留20%安全库存`,
        };
      })(),
       // 分阶段成长路径：0到1→起量→稳定维持→再增长
       growthPath: {
         '0到1·冷启动': [
           '【自然流量】先选好品、优化Listing标题五点主图，埋好核心关键词，确保搜索能被搜到',
           '【广告】先开自动广告跑词（日预算$10-20），跑出好词后转手动精准',
           '【转化率】首批20个评价：Vine+早期评论人计划+Coupon让利冲首单',
           '【库存】首批少量测试（200-500件），跑通数据再决定加不加单',
           '【评分】目标4.3分以上，差评第一时间联系解决',
         ],
         '起量·爬坡期': [
           '【自然流量】关键词上首页：好词加大广告投入+做站外Deal冲销量+BSR排名提升',
           '【广告】从精准词扩到词组+广泛，增加SD/SB广告类型，日预算逐步加到$50-100',
           '【达人/社媒】找中小达人测品发视频（TikTok/YouTube/Instagram），带流量带转化',
           '【转化率】主图视频+A+页面+QA全覆盖，Coupon力度加大，目标转化率到8-12%',
           '【复购】开通Subscribe & Save（订阅制）、做插卡引导加群/留评',
           '【库存】按4-6周销量备货，确保不断货（一断货排名掉一半）',
         ],
         '稳定·维持期': [
           '【关键词排名】守住核心词首页位置，自然位+广告位双占位',
           '【广告】控制ACoS在目标范围内，广告占比降到30%以下，自然单占大头',
           '【评价维护】每天盯评价，有差评第一时间处理；定期邀评，目标4.4-4.5分',
           '【库存安全】安全库存30-45天，海外仓+FBA双仓保障',
           '【复购】邮件营销+私域沉淀，老客复购率目标15%+',
           '【竞品监控】盯紧Top5竞品价格/评价/促销动作，及时应对',
         ],
         '再增长·突破期': [
           '【多链接矩阵】同品类2-3条链接互相配合，占住更多坑位',
            '【多平台】拓展TikTok Shop/美客多等新平台，复制成功经验',
           '【新品开发】基于老品数据和市场趋势，开发互补品和升级款',
           '【品牌化】做品牌旗舰店+品牌广告+品牌故事，建立品牌溢价',
           '【私域沉淀】把买过的客户导到独立站/社媒，降低复购成本',
           '【站外流量】Deal站+Blog+YouTube达人+KOL测评，全方位引流',
         ],
       },
       // 选品与定价打法：产品结构+定价策略达成销售目标
       pricingStrategy: {
         title: '选品与定价打法（用产品结构和价格梯队达成目标）',
         groups: [
           {
             subtitle: '① 低客单价引流款：先把人和订单量拉进来',
             tips: [
               '选便宜、刚需、轻小的低价款（$5-15）做引流，这类东西用户决策快、下单门槛低，能快速把店铺订单量和权重拉起来',
               '引流款不求赚钱甚至可以微亏，靠它把人引进店，然后用店铺里其他利润款把钱赚回来（相当于花钱买流量，但比纯广告便宜）',
               '引流款一定要标「爆款」「热销」标签，主图做醒目一点，配合Coupon/限时折扣加大转化率，订单量起来后店铺整体流量也会涨',
             ],
           },
           {
             subtitle: '② 高客单价利润款：用优惠券代替直接降价',
             tips: [
               '高价产品（$50以上）别直接降价卖，一降价以后价格就涨不回去了，还会把整个品类价格体系压垮',
               '用优惠券（Coupon）、限时折扣（LD/7DD）、满减、买多件打折这些方式制造「到手价很划算」的感觉，用户觉得捡了便宜，但你的标价依然坚挺',
               '优惠券面额控制在10-20%之间，既能提升转化又不会伤利润；配合「倒计时」「仅剩X件」紧迫感效果更好',
             ],
           },
           {
             subtitle: '③ 组合与关联带货：主体+耗材，拉高客单价',
             tips: [
               '卖主体产品的同时，搭配卖配套的小配件和耗材——比如装饰画配挂钩/无痕钉/水平仪、宠物用品配替换滤芯/清洁刷、厨房工具配替换刀片/清洁剂',
               '耗材和配件成本低、复购高、退货率极低，是纯利润来源；而且用户买了主体就有持续买耗材的需求，相当于锁定了长期收入',
               '做「买主体+耗材立减X元」的捆绑套餐，或者在详情页Frequently bought together里自动推荐关联品，客单价能涨20-40%',
             ],
           },
           {
             subtitle: '④ 价格梯队打法：引流款+走量款+利润款三层搭配',
             tips: [
               '一个品类至少布局3个价位的产品：低价引流款（拉流量拉订单）、中价走量款（贡献大部分销量和稳定利润）、高价利润款（赚高毛利，不用卖太多）',
               '引流款价格比竞品低一点，负责把人引进来；用户进店后看到中价款性价比更高、高价款功能更好，一部分人自然会升级购买',
               '目标比例大概是：引流款占订单30%（不亏或微亏）、走量款占50%（主力赚钱）、利润款占20%（拉高整体利润率）',
             ],
           },
           {
             subtitle: '⑤ 更多实操定价技巧',
             tips: [
               '【尾数定价】标价用$19.99而不是$20，$29.95而不是$30，用户心理感受差一个档次，转化能高5-10%',
               '【锚定定价】先放一个高价款在前面当锚点，再主推的中价款就显得「很划算」——比如先展示$79的旗舰款，再推$39的主力款，用户觉得便宜一半',
               '【差异化定价】同款产品不同颜色/尺寸/包装分开定价，让用户有选择空间，也避免所有人都盯着最低价买',
               '【节日/旺季涨价】大促前先涨价再打折（比如平时$29.99，节前涨到$39.99再打7折=$27.99），用户觉得捡了便宜你也没少赚',
               '【捆绑提客单】把2-3个相关产品打包成套装，标价比单独买便宜15-20%，客单价直接翻倍，打包发货还省运费',
             ],
           },
         ],
       },
     };

     return { items, dailyOrders, growthRate, suggestions };
  }, [inputs]);

  function updateInput<K extends keyof ReverseInputs>(key: K, value: string) {
    const num = parseFloat(value) || 0;
    setInputs(prev => ({ ...prev, [key]: num }));
  }

  const inputFields: { key: keyof ReverseInputs; label: string; suffix?: string; placeholder?: string }[] = [
    { key: 'monthlyTarget', label: '月度销售目标', suffix: '$' },
    { key: 'avgOrderValue', label: '平均客单价', suffix: '$' },
    { key: 'conversionRate', label: '目标转化率', suffix: '%' },
    { key: 'adOrderRatio', label: '广告订单占比', suffix: '%' },
    { key: 'maxACoS', label: '广告ACOS', suffix: '%' },
    { key: 'linkDailyOrders', label: '单链接日均出单', suffix: '单' },
    { key: 'operatingDays', label: '每月可运营天数', suffix: '天' },
    { key: 'currentDailyOrders', label: '当前日销（选填）', suffix: '单', placeholder: '填了能算增速' },
  ];

  return (
    <Card
      className="border-0 overflow-hidden"
      style={{
        backgroundColor: theme.ui.glassBg,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        boxShadow: theme.ui.glassShadow,
        border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
      }}
    >
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          <Calculator className="size-5" style={{ color: theme.primary }} />
          目标倒推器
          <Badge
            className="text-xs font-normal ml-1 border-0"
            style={{ backgroundColor: theme.ui.badgeBg, color: theme.primary }}
          >
            输入目标，倒推要做多少事
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-5">
        {/* 输入区 */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {inputFields.map(f => (
             <div key={f.key}>
               <label className="text-xs text-muted-foreground mb-1 block flex items-center gap-1 flex-wrap">
                 {f.label}
                  {f.key === 'conversionRate' && (
                    <span className="text-[10px] text-muted-foreground/70 font-normal">（订单量÷访问量×100%）</span>
                  )}
               </label>
              <div className="relative">
                <Input
                  type="number"
                  value={inputs[f.key] || ''}
                  placeholder={f.placeholder}
                  onChange={(e) => updateInput(f.key, e.target.value)}
                  className="pr-8 text-sm h-9"
                  style={{
                    backgroundColor: theme.ui.formulaCardBg,
                    borderColor: theme.ui.cardBorder,
                  }}
                />
                {f.suffix && (
                  <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                    {f.suffix}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* 结果卡片 */}
        {results && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
              {results.items.map((item, i) => {
                const Icon = item.icon;
                return (
                  <div
                    key={i}
                    className="p-4 rounded-xl transition-all hover:translate-y-[-2px]"
                    style={{
                      backgroundColor: theme.ui.formulaCardBg,
                      border: `1px solid ${theme.ui.cardBorder}`,
                    }}
                  >
                    <div className="flex items-center gap-2 text-xs text-muted-foreground mb-1.5">
                      <Icon className="size-3.5" style={{ color: theme.primary }} />
                      {item.label}
                    </div>
                    <div
                      className="text-2xl font-black tabular-nums"
                      style={{ color: theme.primary }}
                    >
                      {item.value}
                    </div>
                    <div className="text-[11px] text-muted-foreground mt-2 leading-relaxed">
                      公式：{item.formula}
                    </div>
                    {item.note && (
                      <div className="text-[11px] mt-1.5" style={{ color: theme.priority.p1 }}>
                        💡 {item.note}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {/* 增速提示 */}
            {results.growthRate !== null && (
              <div
                className="p-4 rounded-xl border-l-4"
                style={{
                  backgroundColor: theme.ui.riskCardBg,
                  borderLeftColor: theme.priority.p1,
                }}
              >
                <div className="text-sm font-semibold text-foreground flex items-center gap-2">
                  <TrendingUp className="size-4" style={{ color: theme.priority.p1 }} />
                  环比增速提示
                </div>
                <div className="text-xs text-muted-foreground mt-1.5 leading-relaxed">
                  当前日销 {inputs.currentDailyOrders} 单，要达到目标需要每天 <span className="font-semibold" style={{ color: theme.priority.p1 }}>{results.dailyOrders.toFixed(1)} 单</span>，
                  日销需要增长 <span className="font-bold" style={{ color: theme.priority.p1 }}>{results.growthRate}%</span>。
                  {parseFloat(results.growthRate) > 50
                    ? ' 增速超过50%，压力不小，建议拆解到每周逐步提升，别一口吃成胖子。'
                    : parseFloat(results.growthRate) > 20
                    ? ' 增速20-50%，属于冲刺范围，配合广告+促销应该能达到。'
                    : ' 增速在20%以内，属于稳健增长范围，优化优化Listing和广告就能做到。'}
                </div>
              </div>
            )}

            {/* 动态建议推荐 */}
            <Accordion type="single" collapsible className="w-full">
              <AccordionItem value="suggestions" className="border rounded-xl px-4" style={{ borderColor: theme.ui.cardBorder }}>
                <AccordionTrigger className="py-3 hover:no-underline">
                  <div className="flex items-center gap-2 text-sm font-semibold text-foreground">
                    <Lightbulb className="size-4" style={{ color: theme.primary }} />
                    做到这种销售数据的建议推荐
                    <Badge
                      className="text-[10px] font-normal ml-1 border-0"
                      style={{ backgroundColor: theme.ui.badgeBg, color: theme.primary }}
                    >
                      结合你的目标动态生成
                    </Badge>
                  </div>
                </AccordionTrigger>
                <AccordionContent className="pb-4 space-y-4">
                  {/* 流量缺口 */}
                  <div className="p-3 rounded-lg space-y-2" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                    <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: theme.primary }}>
                      <Megaphone className="size-3.5" />
                      流量怎么补（当前日均需 {Math.ceil(results.suggestions.traffic.level === '起步期' ? 50 : results.suggestions.traffic.level === '成长期' ? 200 : results.suggestions.traffic.level === '成熟期' ? 500 : 1000)} 人）— {results.suggestions.traffic.level}
                    </div>
                    <ul className="text-xs text-foreground/80 space-y-1 list-disc list-inside leading-relaxed">
                      {results.suggestions.traffic.tips.map((t, i) => (
                        <li key={i}>{t}</li>
                      ))}
                    </ul>
                  </div>

                  {/* 转化率提升 */}
                  <div className="p-3 rounded-lg space-y-2" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                     <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: results.suggestions.conversion.levelColor === 'destructive' ? 'hsl(0 84% 60%)' : results.suggestions.conversion.levelColor === 'warning' ? 'hsl(26 90% 49%)' : 'hsl(130 54% 42%)' }}>
                       <Target className="size-3.5" />
                       转化率怎么提（当前目标 {inputs.conversionRate}%）— {results.suggestions.conversion.level}
                     </div>
                    <ul className="text-xs text-foreground/80 space-y-1 list-disc list-inside leading-relaxed">
                      {results.suggestions.conversion.tips.map((t, i) => (
                        <li key={i}>{t}</li>
                      ))}
                    </ul>
                     <div className="text-[11px] text-muted-foreground mt-1.5">
                       💡 转化率公式：<span className="font-medium">转化率 = 订单量 ÷ 访问量 × 100%</span>。
                       例：一天进店 100 人、成交 10 单，转化率就是 10%。亚马逊一般 9%~11% 为健康区间，低于 5% 需重点优化，5%~8% 还有提升空间。
                     </div>
                  </div>

                  {/* 广告与自然单占比 */}
                  <div className="p-3 rounded-lg space-y-2" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                    <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: theme.priority.p2 }}>
                      <Star className="size-3.5" />
                      广告单 / 自然单合理比例（目标广告占比 {inputs.adOrderRatio}%）— {results.suggestions.adRatio.level}
                    </div>
                    <p className="text-xs text-foreground/80 leading-relaxed">
                      {results.suggestions.adRatio.tip}
                    </p>
                  </div>

                  {/* 备货与爆款链接 */}
                  <div className="p-3 rounded-lg space-y-2" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                    <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: theme.primary }}>
                      <Warehouse className="size-3.5" />
                      备货量与爆款链接建议
                    </div>
                    <p className="text-xs text-foreground/80 leading-relaxed">
                      {results.suggestions.stock.linksTip}
                    </p>
                    <p className="text-xs text-foreground/80 leading-relaxed">
                      {results.suggestions.stock.stockTip}
                    </p>
                  </div>

                  {/* 分阶段成长路径 */}
                  <div className="p-3 rounded-lg space-y-3" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                    <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: theme.primary }}>
                      <TrendingUp className="size-3.5" />
                      分阶段成长路径（0→1→起量→稳定→再增长）
                    </div>
                    <div className="grid grid-cols-1 gap-2">
                      {Object.entries(results.suggestions.growthPath).map(([stage, tips]) => (
                        <div key={stage} className="border border-border/40 rounded-md p-2.5 bg-background/40">
                            <div className="text-xs font-semibold mb-1.5" style={{ color: theme.primary }}>
                              ▶ {stage}
                            </div>
                            <ul className="text-[11px] text-foreground/80 space-y-0.5 list-disc list-inside leading-relaxed">
                              {(tips as string[]).map((t, i) => (
                                <li key={i}>{t}</li>
                              ))}
                            </ul>
                          </div>
                      ))}
                    </div>
                  </div>

                  {/* 选品与定价打法 */}
                  <div className="p-3 rounded-lg space-y-3" style={{ backgroundColor: theme.ui.formulaCardBg }}>
                    <div className="flex items-center gap-2 text-xs font-semibold" style={{ color: theme.primary }}>
                      <Tag className="size-3.5" />
                      {results.suggestions.pricingStrategy.title}
                    </div>
                    <div className="space-y-2.5">
                      {results.suggestions.pricingStrategy.groups.map((group) => (
                        <div key={group.subtitle} className="border border-border/40 rounded-md p-2.5 bg-background/40">
                          <div className="text-xs font-semibold mb-1.5" style={{ color: theme.primary }}>
                            {group.subtitle}
                          </div>
                          <ul className="text-[11px] text-foreground/80 space-y-0.5 list-disc list-inside leading-relaxed">
                            {group.tips.map((t, i) => (
                              <li key={i}>{t}</li>
                            ))}
                          </ul>
                        </div>
                      ))}
                    </div>
                  </div>
                </AccordionContent>
              </AccordionItem>
            </Accordion>

            <div className="text-center text-xs text-muted-foreground pt-1">
              系统算目标，人做判断 —— 数字是方向，具体节奏自己掌握
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

export default GoalReverseCard;
